<script setup>
import {ref} from 'vue'

import HelpTip from '../shared/components/HelpTip.vue'
import {toast} from '../shared/composables/toast.js'
import {formatJSON,switchBodyType} from './requestEditorModel.js'
const props=defineProps({editor:{type:Object,required:true},disabled:Boolean}),input=ref(null),reading=ref(false)
defineExpose({focus:()=>focusControl(input.value)})
function format(){try{props.editor.request.body=formatJSON(props.editor.request.body)}catch{toast('正文不是有效 JSON，已保留原内容','warning')}}
async function choose(file,row){reading.value=true;props.editor.uploading=true;const request=props.editor.request,type=request.body_type;try{if(file.size>256*1024)throw Error('单次请求的文件和表单内容合计不能超过 256 KiB');const raw=new Uint8Array(await file.arrayBuffer());if(props.editor.request!==request||request.body_type!==type)return false;let bytes='';for(const b of raw)bytes+=String.fromCharCode(b);const value={name:file.name,content_type:file.type||'application/octet-stream',data_base64:btoa(bytes)};if(row)row.file=value;else request.file=value}catch(e){toast(e.message,'warning')}finally{reading.value=false;props.editor.uploading=false}return false}
function fieldType(row,type){row.value='';if(type==='file')row.file={name:'',content_type:'application/octet-stream',data_base64:''};else delete row.file}

import OptionPicker from '../shared/components/OptionPicker.vue'

import {focusControl} from '../shared/focusControl.js'


import {Badge,Button,Empty,EmptyDescription,EmptyHeader,Input,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Textarea} from '../shared/shadcn-ui.js'
</script>
<template><section><div class="body-tools"><OptionPicker :model-value="editor.request.body_type||''" :disabled="disabled||reading" aria-label="请求正文类型" style="width:min(310px,100%)" @change="type=>switchBodyType(editor,type)" :options="[{value:'',label:'原始正文'},{value:'json',label:'JSON'},{value:'text',label:'文本'},{value:'urlencoded',label:'表单 x-www-form-urlencoded'},{value:'multipart',label:'表单 multipart / 文件'},{value:'binary',label:'二进制文件'}]"/><Button v-if="['','json','text'].includes(editor.request.body_type||'')" @click="format" variant="ghost" size="default" type="button" :disabled="(disabled||!editor.request.body)">格式化 JSON</Button><HelpTip text="文件由浏览器选择，和用例一起加密保存，报告不保存文件内容。文件和表单原始内容合计上限 256 KiB；表单字段支持变量引用。切换正文类型保留本地草稿。"/></div><div v-if="['urlencoded','multipart'].includes(editor.request.body_type)" class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:620}).y?({x:620}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:620}).x||({x:620}).minWidth||530)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(180)+'px'}">字段名</TableHead><TableHead v-if="editor.request.body_type==='multipart'" :style="{width:(120)+'px'}">类型</TableHead><TableHead>值 / 文件</TableHead><TableHead :style="{width:(80)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (editor.request.form||[]||[])" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Input v-model="record.name" :disabled="disabled||reading" aria-label="表单字段名"/></template></div></TableCell><TableCell v-if="editor.request.body_type==='multipart'" class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><OptionPicker :model-value="record.file?'file':'text'" :disabled="disabled||reading" aria-label="表单字段类型" @change="v=>fieldType(record,v)" class="min-w-36" :options="[{value:'text',label:'文本'},{value:'file',label:'文件'}]"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><div v-if="record.file" class="flex flex-wrap items-center gap-2"><div class="inline-flex min-w-0 items-center gap-2"><Input type="file" aria-label="选择上传文件" class="max-w-xs" :disabled="disabled||reading" @change="e=>{for(const file of e.target.files||[])(file=>choose(file,record))(file);e.target.value=''}"/></div><Badge variant="secondary">{{record.file.name||'尚未选择文件'}}</Badge></div><Input v-else v-model="record.value" :disabled="disabled||reading" placeholder="值或 {{case.order_id}}" aria-label="表单字段值"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{rowIndex} in [{record,rowIndex}]"><Button @click="editor.request.form.splice(rowIndex,1)" variant="ghost" size="default" type="button" :disabled="(disabled||reading)">移除</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(editor.request.form||[]||[]).length"><TableCell :colspan="4"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><Button v-if="['urlencoded','multipart'].includes(editor.request.body_type)" @click="(editor.request.form||=([])).push({name:'',value:''})" class="add-field" variant="outline" size="default" type="button" :disabled="(disabled||reading||(editor.request.form?.length||0)>=30)">添加表单字段</Button><div v-else-if="editor.request.body_type==='binary'" class="flex flex-wrap items-center gap-2"><div class="inline-flex min-w-0 items-center gap-2"><Input type="file" aria-label="选择上传文件" class="max-w-xs" :disabled="disabled||reading" @change="e=>{for(const file of e.target.files||[])(file=>choose(file))(file);e.target.value=''}"/></div><Badge variant="secondary">{{editor.request.file?.name||'尚未选择文件'}}</Badge></div><Textarea v-else ref="input" v-model="editor.request.body" :disabled="disabled" placeholder="填写请求正文" aria-label="请求正文" :rows="({minRows:6,maxRows:18}).minRows||4"/></section></template>
<style scoped>.body-tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.add-field{margin-top:12px}</style>
